    {
      "id": "FAM:SF-APPA-017",
      "status_as_recorded": "rejected",
      "finding": "Routing possessions to each play type's best player adds value over A3, and survives defensive attention adaptation. V4 A5 vs A3 +0.77; V5 +0.94 (A5b vs A5 +0.01); V6 (520 matchups) A5 vs A3 +0.03, A5b vs A5 -0.00."
    },
    {
      "id": "FAM:SF-PAP-008",
      "status_as_recorded": "inconclusive",
      "finding": "d_entropy_nonfocal=-0.0455 (shaper, n_ts=80); organizer +0.0115"
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPA-005",
      "what_failed": "Measuring defensive scheme change using inferred labels.",
      "why": "A_unanswerable (question not answerable with the data or design); inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
    },
