      "id": "FAM:SF-APPS-025",
      "what_failed": "Testing if teams abandoning a suppressed play type show a smaller overall offense excess decline.",
      "why": "A_unanswerable (question not answerable with the data or design); Group B caliper-0.10 CI includes 0 (p=0.386, n=255 clusters=242); Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample."
    },
    {
      "id": "FAM:SF-APPM-021",
      "what_failed": "Descriptive analysis of within-game tactical adaptation (halftime, crunch, post-run) using play-type mix shifts.",
      "why": "E_unclear (mechanism unclear from the records); No inferential tests; OTHER label known to be noisy (PT audit)."
    },
    {
      "id": "FAM:SF-CHT-052",
      "what_failed": "Using similar-profile teammates to separate absorption from cascade when a player sits.",
      "why": "B_powered_null (adequately powered null result); Similarity does not separate absorption from cascade; almost always findable."
    },
    {
      "id": "FAM:SF38",
      "what_failed": "Detecting defensive in-game adaptation to repeated play type (exposure slope) on PPP.",
      "why": "LIM:insufficient_exposure; LIM:label_or_classification_error; LIM:low_measurement_reliability"
    },
    {
      "id": "FAM:SF-CHT-064",
      "what_failed": "Establishing team-season defensive H2-adjustment as a reliable trait.",
      "why": "A_unanswerable (question not answerable with the data or design); Split-half r=-0.001; a detectable r needs about 0.18. Offensive H2-change r=+0.139 ns."
    }
